# Chapter 24 Magnetic fields and electromagnetism — part b: 24.5 to 24.8.
MU0 = 4 * pi * 1e-7
GW = 2e-7
MU = ' Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.'
QE, ME, MP = 1.60e-19, 9.11e-31, 1.67e-27

# ═════════════════════════ 24.5 Currents crossing fields (16/18/10) ═════════════════════════
lesson('24.5')
N('E', 2, 'A 0.12 m length of wire carries 2.0 A at right angles to a uniform field of 0.25 T. Calculate the force on it.', 0.25 * 2.0 * 0.12, 'N',
  'F = BIL = 0.25 × 2.0 × 0.12 = 0.060 N', ['C1: F = BIL'], sig=2, aq='F')
N('E', 2, 'A 0.20 m wire carrying 5.0 A crosses a 0.10 T field at 30° to the field lines. Calculate the force on the wire.', 0.10 * 5.0 * 0.20 * sin(radians(30)), 'N',
  'F = BIL sin θ = 0.10 × 5.0 × 0.20 × sin 30° = 0.050 N', ['C1: F = BIL sin θ'], sig=2, aq='F')
M('E', 1, 'At what angle between a current-carrying wire and a uniform magnetic field is the force on the wire zero?', '0°', ['90°', '45°', '60°'], 'F = BIL sin θ, and sin 0° = 0: the wire is along the field.')
N('E', 2, 'A uniform field of 0.50 T makes an angle of 40° with a straight wire. Calculate the component of the field at right angles to the wire.', 0.50 * sin(radians(40)), 'T',
  f'B⊥ = B sin 40° = 0.50 × sin 40° = {sf(0.5 * sin(radians(40)))} T', ['C1: B sin θ'], aq='B⊥')
M('E', 1, 'A horizontal wire carries a current due east in a horizontal field pointing due north. In which direction is the force on the wire?', 'Vertically upwards', ['Vertically downwards', 'Due west', 'Due south'], 'Left-hand rule: first finger north, second finger east, thumb points up.')
N('E', 2, 'A cable carrying 10 A crosses a 0.20 T field at 60° to the field lines. Calculate the force on each metre of the cable.', 0.20 * 10 * sin(radians(60)), 'N m⁻¹',
  f'F/L = BI sin θ = 0.20 × 10 × sin 60° = {sf(2 * sin(radians(60)))} N m⁻¹', ['C1: F/L = BI sin θ'], aq='F/L')
M('E', 1, 'In the equation F = BIL sin θ, what is θ?', 'The angle between the wire (current direction) and the magnetic field', ['The angle between the force and the field', 'The angle between the wire and the force', 'The angle the wire makes with the horizontal'], 'Only the component of B at right angles to the current matters.')
N('E', 2, 'A wire feels its largest possible force, 0.30 N, when at right angles to a field. When it is turned, the force becomes 0.26 N. Calculate the new angle between wire and field.', degrees(asin(0.26 / 0.30)), '°',
  f'sin θ = 0.26 ÷ 0.30 = {sf(0.26 / 0.3, 4)}, so θ = sin⁻¹ {sf(0.26 / 0.3, 4)} = {sf(degrees(asin(0.26 / 0.3)))}°', ['C1: F/F_max = sin θ'], aq='θ')
M('E', 1, 'A wire at right angles to a field is turned until it lies along the field, pointing the opposite way (θ = 180°). What is the force on it now?', 'Zero', ['The same as at 90°', 'Twice the force at 90°', 'The same size but reversed'], 'F = BIL sin θ and sin 180° = 0: a wire along the field, either way, feels no force.')
N('E', 2, 'What length of wire carrying 2.0 A at right angles to a 0.30 T field experiences a force of 0.090 N?', 0.090 / (0.30 * 2.0), 'm',
  'L = F/(BI) = 0.090 ÷ (0.30 × 2.0) = 0.15 m', ['C1: L = F/(BI)'], sig=2, aq='L')
M('E', 1, 'How is the direction of the force on a current-carrying wire related to the wire and the field?', 'It is at right angles to both the wire and the field', ['It is along the field', 'It is along the wire', 'It is at 45° to the field'], 'The magnetic force is perpendicular to the plane containing the current and B.')
N('E', 2, 'A 0.50 m wire carrying 4.0 A lies at 75° to a field of 0.060 T. Calculate the force on it.', 0.060 * 4.0 * 0.50 * sin(radians(75)), 'N',
  f'F = BIL sin θ = 0.060 × 4.0 × 0.50 × sin 75° = {sf(0.12 * sin(radians(75)))} N', ['C1: F = BIL sin θ'], aq='F')
M('E', 1, 'A horizontal wire is turned to point in different compass directions in a uniform vertical field. What happens to the size of the force on it?', 'It stays the same, because the wire is always at right angles to the field', ['It is largest when the wire points north', 'It becomes zero when the wire points east', 'It doubles when the wire points south'], 'A horizontal wire is always perpendicular to a vertical field.')
N('E', 1, 'A wire at 90° to a field feels a force of 0.40 N. What force does it feel at 150° to the field?', 0.40 * sin(radians(150)), 'N',
  'F = 0.40 × sin 150° = 0.20 N', [], sig=2, aq='F')
M('E', 1, 'A field is resolved into a component along a wire and a component at right angles to it. Which component produces the force on the wire?', 'Only the component at right angles to the wire', ['Only the component along the wire', 'Both components equally', 'Neither component'], 'The parallel component exerts no force on the current.')
N('E', 2, 'A 0.10 m wire carrying 1.0 A at 45° to a field experiences a force of 0.035 N. Calculate the flux density.', 0.035 / (1.0 * 0.10 * sin(radians(45))), 'T',
  f'B = F/(IL sin θ) = 0.035 ÷ (1.0 × 0.10 × sin 45°) = {sf(0.035 / (0.1 * sin(radians(45))))} T', ['C1: rearranged F = BIL sin θ'], aq='B')
# medium
N('M', 3, 'Find the force on 0.25 m of conductor carrying 3.0 A when a 0.20 T field crosses it at 25°.', 0.20 * 3.0 * 0.25 * sin(radians(25)), 'N',
  f'F = BIL sin θ = 0.20 × 3.0 × 0.25 × sin 25° = {sf(0.15 * sin(radians(25)))} N', ['C1: F = BIL sin θ', 'C1: substitution'], aq='F')
N('M', 3, 'A vertical cable 5.0 m long carries 30 A. The Earth\'s field has a horizontal component of 2.0 × 10⁻⁵ T and a vertical component of 4.5 × 10⁻⁵ T. Calculate the force on the cable.', 2.0e-5 * 30 * 5.0, 'N',
  'Only the horizontal component is at right angles to a vertical cable: F = 2.0 × 10⁻⁵ × 30 × 5.0 = 3.0 × 10⁻³ N', ['B1: only the horizontal component acts', 'C1: F = BIL'], sig=2, aq='F')
M('M', 3, 'A vertical wire carries a current upwards where the Earth\'s horizontal field points north. In which direction is the force on the wire?', 'Due west', ['Due east', 'Due north', 'Vertically downwards'], 'Left-hand rule: first finger north, second finger up, thumb points west.', ['C1: horizontal component', 'C1: left-hand rule'])
N('M', 4, 'A horizontal cable 5.0 m long runs north–south and carries 30 A. The Earth\'s field has a horizontal component of 2.0 × 10⁻⁵ T (northwards) and a vertical component of 4.5 × 10⁻⁵ T. Calculate the force on the cable.', 4.5e-5 * 30 * 5.0, 'N',
  'The horizontal component is parallel to the cable and gives no force; the vertical component is perpendicular: F = 4.5 × 10⁻⁵ × 30 × 5.0 = 6.75 × 10⁻³ N', ['B1: horizontal component parallel, no force', 'C1: vertical component used', 'C1: F = BIL'], aq='F')
N('M', 3, 'For a wire in a field, BIL = 0.25 N. Calculate the largest angle between the wire and the field for which the force is no more than 0.10 N.', degrees(asin(0.10 / 0.25)), '°',
  f'sin θ = 0.10 ÷ 0.25 = 0.40, so θ = sin⁻¹ 0.40 = {sf(degrees(asin(0.4)))}°', ['C1: F = BIL sin θ', 'C1: inverse sine'], aq='θ')
M('M', 3, 'A wire is rotated in a uniform field from θ = 0° to θ = 180°, where θ is the angle between wire and field. Which describes the graph of force against θ?', 'Half a sine wave: zero at 0°, a maximum at 90°, zero at 180°', ['A straight line rising from 0° to 180°', 'A constant value', 'Zero at 90° and maximum at 0° and 180°'], 'F = BIL sin θ, so the graph follows sin θ between 0° and 180°.', ['C1: F ∝ sin θ', 'C1: maximum at 90°'])
N('M', 3, 'An L-shaped wire has one 0.10 m arm at right angles to a 0.50 T field and the other 0.10 m arm parallel to it. A current of 2.0 A flows. Calculate the total force on the wire.', 0.50 * 2.0 * 0.10, 'N',
  'Only the perpendicular arm feels a force: F = 0.50 × 2.0 × 0.10 = 0.10 N', ['B1: parallel arm feels no force', 'C1: F = BIL'], sig=2, aq='F')
N('M', 4, 'A wire bent at a right angle has arms of 0.30 m and 0.40 m, both in a plane at right angles to a 0.20 T field. It carries 3.0 A. Calculate the resultant force on the wire.', 0.20 * 3.0 * 0.50, 'N',
  'Forces: 0.20 × 3.0 × 0.30 = 0.18 N and 0.20 × 3.0 × 0.40 = 0.24 N, at right angles. Resultant = √(0.18² + 0.24²) = 0.30 N', ['C1: force on each arm', 'M1: forces perpendicular', 'C1: resultant'], sig=2, aq='F')
M('M', 4, 'A closed rectangular loop carrying a current lies in a uniform magnetic field. Which statement is correct?', 'The resultant force on the loop is zero, but there may be a turning effect', ['There is always a resultant force towards the north pole', 'There is never any turning effect', 'The resultant force equals BIL for one side'], 'Forces on opposite sides are equal and opposite; if they are not in line they form a couple.', ['C1: opposite sides opposite forces', 'C1: resultant zero', 'C1: possible couple'])
N('M', 3, 'A power cable carrying 400 A runs at 35° to the Earth\'s field of 5.0 × 10⁻⁵ T. Calculate the force on each metre of cable.', 5.0e-5 * 400 * sin(radians(35)), 'N m⁻¹',
  f'F/L = BI sin θ = 5.0 × 10⁻⁵ × 400 × sin 35° = {sf(0.02 * sin(radians(35)))} N m⁻¹', ['C1: F/L = BI sin θ', 'C1: substitution'], aq='F/L')
N('M', 3, 'A 0.60 m wire carrying 0.50 A in a 0.10 T field feels a force of 0.020 N. Calculate the angle between the wire and the field.', degrees(asin(0.020 / (0.10 * 0.50 * 0.60))), '°',
  f'sin θ = 0.020 ÷ (0.10 × 0.50 × 0.60) = {sf(0.02 / 0.03, 4)}, so θ = sin⁻¹ {sf(0.02 / 0.03, 4)} = {sf(degrees(asin(0.02 / 0.03)))}°', ['C1: rearranged', 'C1: inverse sine'], aq='θ')
M('M', 3, 'A wire lies along the +y direction carrying current in that direction. A uniform field points in the +z direction. What is the direction of the force on the wire?', '+x', ['−x', '+z', '−y'], 'F is along IL × B: (+y) × (+z) = +x.', ['C1: perpendicular to wire and field', 'C1: correct sense'])
N('M', 3, 'A wire at 30° to a field feels a force F. To what angle must it be turned for the force to be 2F?', degrees(asin(2 * 0.5)), '°',
  'sin θ = 2 × sin 30° = 1.0, so θ = sin⁻¹ 1.0 = 90°', ['C1: F ∝ sin θ', 'C1: sin θ = 1'], sig=2, aq='θ')
N('M', 4, 'A 25-turn motor coil has sides 0.080 m long that stay at right angles to a 0.30 T field as it rotates. The current is 0.60 A and the coil is 0.050 m wide. Calculate the torque when the plane of the coil is at 30° to the field.', 25 * 0.30 * 0.60 * 0.080 * 0.050 * cos(radians(30)), 'N m',
  f'F = NBIL = 25 × 0.30 × 0.60 × 0.080 = 0.36 N on each side. The perpendicular distance between the forces is 0.050 × cos 30°, so torque = 0.36 × 0.050 × cos 30° = {sf(0.36 * 0.05 * cos(radians(30)))} N m', ['C1: F = NBIL', 'M1: perpendicular distance', 'C1: torque'], aq='torque')
M('M', 3, 'Why does the force on each long side of a motor coil stay the same size as the coil rotates?', 'Those sides stay at right angles to the field throughout the rotation', ['The current increases as the coil turns', 'The field gets stronger near the poles', 'The commutator keeps the force constant'], 'The sides are parallel to the axis, which is perpendicular to B; only the turning effect changes.', ['C1: sides remain perpendicular', 'C1: F = BIL constant'])
N('M', 3, 'In an electric motor, 0.25 m of winding carrying 12 A sits at 60° to a 0.080 T field. Determine the force on this winding.', 0.080 * 12 * 0.25 * sin(radians(60)), 'N',
  f'F = BIL sin θ = 0.080 × 12 × 0.25 × sin 60° = {sf(0.24 * sin(radians(60)))} N', ['C1: F = BIL sin θ', 'C1: substitution'], aq='F')
N('M', 3, 'A 0.40 m wire lies at 50° to a 0.25 T field. Calculate the current needed for a force of 0.050 N.', 0.050 / (0.25 * 0.40 * sin(radians(50))), 'A',
  f'I = F/(BL sin θ) = 0.050 ÷ (0.25 × 0.40 × sin 50°) = {sf(0.05 / (0.1 * sin(radians(50))))} A', ['C1: rearranged', 'C1: substitution'], aq='I')
M('M', 3, 'A wire at 90° to a field has its angle changed to 60° and its current doubled. By what factor does the force change?', 'About 1.7', ['2', '1', '0.87'], 'Factor = 2 × sin 60° ÷ sin 90° = 1.73.', ['C1: F ∝ I sin θ', 'C1: 2 × 0.87'])
# hard
N('H', 6, 'A wire 0.050 m long carrying 2.0 A is placed at different angles θ to a field: θ/° = 0, 30, 60, 90 and F/mN = 0, 15, 26, 30. (a) Calculate sin θ for each reading. (b) Explain why a graph of F against sin θ should be a straight line through the origin. (c) Use the 90° reading to find the flux density. (d) Predict the force at 45°, in mN. Give only the answer to (c).', 30e-3 / (2.0 * 0.050), 'T',
  f'(a) sin θ = 0, 0.50, 0.87, 1.0. (b) F = (BIL) sin θ, with gradient BIL. (c) B = F/(IL) = 30 × 10⁻³ ÷ (2.0 × 0.050) = 0.30 T. (d) F = 30 × sin 45° = {sf(30 * sin(radians(45)))} mN',
  ['C1: sin θ values', 'B1: F ∝ sin θ', 'M1: gradient = BIL', 'C1: B', 'C1: prediction'], sig=2, aq='B')
N('H', 5, 'A lightning strike sends a current of 20 kA down a vertical lightning conductor 10 m tall. The Earth\'s horizontal field there is 2.0 × 10⁻⁵ T. (a) Explain why only the horizontal component of the Earth\'s field matters. (b) Calculate the force on the conductor. (c) State the direction of the force relative to the horizontal field. Give only the answer to (b).', 2.0e-5 * 20e3 * 10, 'N',
  '(a) The vertical component is parallel to the conductor and gives no force. (b) F = BIL = 2.0 × 10⁻⁵ × 20 × 10³ × 10 = 4.0 N. (c) Horizontal and at right angles to the horizontal field (east or west depending on the current direction).',
  ['B1: vertical component parallel', 'C1: F = BIL', 'C1: substitution', 'B1: direction perpendicular to B_h'], sig=2, aq='F')
N('H', 6, 'A wire PQR has PQ = 0.20 m along the +x direction and QR = 0.15 m along the +y direction. A uniform field of 0.40 T points in the +z direction, and a current of 5.0 A flows from P to R. (a) Calculate the force on PQ and state its direction. (b) Calculate the force on QR and state its direction. (c) Calculate the resultant force. Give only the answer to (c).', 0.40 * 5.0 * sqrt(0.20 ** 2 + 0.15 ** 2), 'N',
  '(a) F_PQ = 0.40 × 5.0 × 0.20 = 0.40 N, along −y. (b) F_QR = 0.40 × 5.0 × 0.15 = 0.30 N, along +x. (c) Resultant = √(0.40² + 0.30²) = 0.50 N',
  ['C1: F on PQ', 'B1: direction −y', 'C1: F on QR', 'B1: direction +x', 'C1: resultant'], sig=2, aq='F')
N('H', 5, 'A 0.50 m wire lies along the x-axis carrying 2.0 A. The field has a component of 0.30 T along x and 0.40 T along y. (a) Explain which component produces a force. (b) Calculate the force on the wire. (c) Calculate the angle between the wire and the resultant field. Give only the answer to (b).', 0.40 * 2.0 * 0.50, 'N',
  f'(a) Only the y-component, which is at right angles to the wire. (b) F = 0.40 × 2.0 × 0.50 = 0.40 N, along z. (c) tan θ = 0.40 ÷ 0.30, so θ = tan⁻¹ 1.333 = {sf(degrees(atan(0.4 / 0.3)))}°; check: B sin θ = 0.50 × sin {sf(degrees(atan(0.4 / 0.3)))}° = 0.40 T.',
  ['B1: perpendicular component only', 'C1: F = B⊥IL', 'C1: angle', 'B1: consistent with B sin θ'], sig=2, aq='F')
N('H', 6, 'A rectangular coil of 40 turns, 0.050 m by 0.040 m, carries 0.50 A in a uniform field of 0.20 T. The torque on it is NBIA cos φ, where φ is the angle between the plane of the coil and the field. (a) Calculate NBIA. (b) Calculate the torque when φ = 60°. (c) Explain why the torque is zero when φ = 90°. Give only the answer to (b).', 40 * 0.20 * 0.50 * 0.050 * 0.040 * cos(radians(60)), 'N m',
  f'(a) NBIA = 40 × 0.20 × 0.50 × 0.050 × 0.040 = 8.0 × 10⁻³ N m. (b) Torque = 8.0 × 10⁻³ × cos 60° = {sf(8e-3 * 0.5)} N m. (c) With the plane perpendicular to B, the forces on opposite sides act along the same line, so they have no turning effect.',
  ['C1: area in m²', 'C1: NBIA', 'M1: × cos φ', 'C1: value', 'B1: forces in line'], sig=2, aq='torque')
N('H', 5, 'The Earth\'s field at a place is 50 µT at a dip angle of 65°, in the north–vertical plane. A horizontal cable 20 m long carries 100 A. (a) Calculate the force on the cable when it runs east–west. (b) Calculate the force when it runs north–south. Give only the answer to (b).', 50e-6 * sin(radians(65)) * 100 * 20, 'N',
  f'(a) East–west is at right angles to the whole field: F = 50 × 10⁻⁶ × 100 × 20 = 0.10 N. (b) North–south: only the vertical component, 50 × sin 65° = {sf(50 * sin(radians(65)))} µT, is perpendicular: F = {sf(50 * sin(radians(65)), 4)} × 10⁻⁶ × 100 × 20 = {sf(50e-6 * sin(radians(65)) * 2000)} N',
  ['C1: east–west uses full B', 'M1: north–south uses vertical component', 'C1: B sin 65°', 'C1: force'], aq='F')
N('H', 6, 'A metal rod of mass 0.050 kg rests across two smooth rails 0.20 m apart, which slope at 30° to the horizontal. A uniform vertical field of 0.50 T acts, and a current flows through the rod. (a) Explain why the magnetic force on the rod is horizontal. (b) Show that, for equilibrium, the magnetic force F satisfies F = mg tan 30°. (c) Calculate the current needed. Give only the answer to (c).' + take('g'), 0.050 * g * tan(radians(30)) / (0.50 * 0.20), 'A',
  f'(a) The force is perpendicular to both the horizontal rod and the vertical field, so it is horizontal. (b) Resolving along the slope: F cos 30° = mg sin 30°, so F = mg tan 30°. (c) F = 0.050 × 9.81 × tan 30° = {sf(0.05 * 9.81 * tan(radians(30)))} N; I = F/(BL) = {sf(0.05 * 9.81 * tan(radians(30)), 4)} ÷ (0.50 × 0.20) = {sf(0.05 * 9.81 * tan(radians(30)) / 0.1)} A',
  ['B1: horizontal force', 'M1: resolve along the slope', 'C1: F = mg tan 30°', 'C1: I = F/(BL)', 'C1: value'], aq='I')
N('H', 5, 'A wire feels 0.36 N when at right angles to a uniform field. (a) Write an expression for the force at angle θ. (b) Calculate the smallest angle between 0° and 90° at which the force is 0.18 N. (c) State the range of angles between 0° and 180° for which the force exceeds 0.18 N. Give only the answer to (b).', degrees(asin(0.18 / 0.36)), '°',
  '(a) F = 0.36 sin θ. (b) sin θ = 0.18 ÷ 0.36 = 0.50, so θ = sin⁻¹ 0.50 = 30°. (c) Between 30° and 150°.',
  ['C1: F = F_max sin θ', 'C1: sin θ = 0.50', 'C1: 30°', 'B1: 30° < θ < 150°'], sig=2, aq='θ')
N('H', 5, '(a) By resolving the field into components along and at right angles to a wire, show that the force on the wire is BIL sin θ. (b) Calculate the force on a 0.40 m wire carrying 6.0 A at 35° to a field of 0.15 T. Give only the answer to (b).', 0.15 * 6.0 * 0.40 * sin(radians(35)), 'N',
  f'(a) The component B cos θ along the wire exerts no force; the component B sin θ is perpendicular, giving F = (B sin θ)IL. (b) F = 0.15 × 6.0 × 0.40 × sin 35° = {sf(0.36 * sin(radians(35)))} N',
  ['B1: parallel component gives no force', 'B1: perpendicular component B sin θ', 'C1: substitution', 'C1: value'], aq='F')
N('H', 6, 'Two parallel rails are 0.10 m apart in a vertical field of 0.40 T. A straight rod is laid across them at 60° to the rails, and carries 3.0 A. (a) Calculate the length of rod between the rails. (b) Calculate the magnetic force on the rod. (c) Calculate the component of this force along the rails. Give only the answer to (c).', 0.40 * 3.0 * 0.10, 'N',
  f'(a) L = 0.10 ÷ sin 60° = {sf(0.1 / sin(radians(60)))} m. (b) The rod is perpendicular to the vertical field: F = 0.40 × 3.0 × {sf(0.1 / sin(radians(60)), 4)} = {sf(1.2 * 0.1 / sin(radians(60)))} N, perpendicular to the rod. (c) Along the rails: {sf(1.2 * 0.1 / sin(radians(60)), 4)} × sin 60° = 0.12 N, the same as for a rod at right angles to the rails.',
  ['C1: L = d/sin 60°', 'C1: F = BIL', 'M1: resolve along rails', 'C1: value', 'B1: equals BId'], sig=2, aq='F')

# ═════════════════════════ 24.6 Forces between currents (17/18/9) ═════════════════════════
lesson('24.6')
M('E', 1, 'Why do two parallel wires carrying currents exert forces on each other?', 'Each wire lies in the magnetic field of the other, so each carries a current in a field', ['Their electric charges attract', 'Their weights pull them together', 'The currents heat the air between them'], 'Wire 2 is in the field of wire 1 and feels F = BIL, and vice versa.')
N('E', 2, 'The force per metre between two long parallel wires is F/L = µ₀I₁I₂/2πd. Calculate it for two wires 0.10 m apart, each carrying 10 A.' + MU, GW * 10 * 10 / 0.10, 'N m⁻¹',
  'F/L = 2.0 × 10⁻⁷ × 10 × 10 ÷ 0.10 = 2.0 × 10⁻⁴ N m⁻¹', ['C1: F/L = µ₀I₁I₂/2πd'], sig=2, aq='F/L')
M('E', 1, 'Two parallel wires carry currents of 2.0 A and 8.0 A. How do the forces on the two wires compare?', 'They are equal in size and opposite in direction', ['The force on the 8.0 A wire is four times larger', 'The force on the 2.0 A wire is four times larger', 'Only the 8.0 A wire feels a force'], 'Newton\'s third law: the forces form an interaction pair.')
N('E', 2, 'Wire 1 carries 5.0 A. Calculate the flux density it produces at wire 2, 0.050 m away, in µT. (B = µ₀I/2πr.)' + MU, GW * 5.0 / 0.050 * 1e6, 'µT',
  'B = 2.0 × 10⁻⁷ × 5.0 ÷ 0.050 = 2.0 × 10⁻⁵ T. In µT: 2.0 × 10⁻⁵ × 10⁶ = 20', ['C1: B = µ₀I/2πr'], sig=2, aq='B')
N('E', 2, 'Wire 2 carries 3.0 A and lies in a field of 2.0 × 10⁻⁵ T produced by a parallel wire 1. Calculate the force on 2.0 m of wire 2.', 2.0e-5 * 3.0 * 2.0, 'N',
  'F = BIL = 2.0 × 10⁻⁵ × 3.0 × 2.0 = 1.2 × 10⁻⁴ N', ['C1: F = BIL'], sig=2, aq='F')
M('E', 1, 'Two parallel wires attract each other. The current in one of them is reversed. What happens?', 'They repel each other with a force of the same size', ['They attract more strongly', 'The force becomes zero', 'They still attract with the same force'], 'Like currents attract; unlike currents repel.')
N('E', 1, 'The force between two parallel wires is 6.0 µN. One current is tripled. What is the new force, in µN?', 18, 'µN', 'F ∝ I₁I₂: 3 × 6.0 = 18 µN', [], sig=2, aq='F')
M('E', 1, 'Two long parallel wires lie side by side. At the position of wire 2, what is the direction of the magnetic field due to wire 1?', 'At right angles to the plane containing the two wires', ['Along wire 2', 'Along the line joining the wires', 'In the direction of the current in wire 1'], 'The circular field lines of wire 1 cross wire 2 at right angles to that plane.')
N('E', 2, 'Calculate the force per metre between two long parallel wires 1.0 m apart, each carrying 1.0 A. (F/L = µ₀I₁I₂/2πd.)' + MU, GW, 'N m⁻¹',
  'F/L = 2.0 × 10⁻⁷ × 1.0 × 1.0 ÷ 1.0 = 2.0 × 10⁻⁷ N m⁻¹: the value once used to define the ampere', ['C1: substitution'], sig=2, aq='F/L')
M('E', 1, 'During a short circuit, two parallel strands of a cable carry very large currents in the same direction. What tends to happen to the strands?', 'They are pulled together', ['They are pushed apart', 'Nothing happens', 'They twist apart'], 'Parallel currents in the same direction attract.')
N('E', 2, 'The force between two parallel wires 6.0 cm apart is 4.0 mN. What is it when they are moved to 3.0 cm apart, with the same currents, in mN?', 4.0 * 6.0 / 3.0, 'mN',
  'F ∝ 1/d: 4.0 × 6.0 ÷ 3.0 = 8.0 mN', ['C1: F ∝ 1/d'], sig=2, aq='F')
M('E', 1, 'Two parallel wires carry different currents. Which wire experiences the larger force?', 'Neither: the forces are equal in size', ['The one with the larger current', 'The one with the smaller current', 'The one that is longer'], 'F = µ₀I₁I₂L/2πd is the same expression for both wires.')
N('E', 2, 'Two long parallel wires 0.020 m apart carry equal currents. The force per metre between them is 1.0 × 10⁻⁴ N m⁻¹. Calculate the current. (F/L = µ₀I²/2πd.)' + MU, sqrt(1.0e-4 * 0.020 / GW), 'A',
  f'I² = (F/L) × d ÷ (µ₀/2π) = 1.0 × 10⁻⁴ × 0.020 ÷ 2.0 × 10⁻⁷ = 10, so I = √10 = {sf(sqrt(10))} A', ['C1: rearranged for I²'], aq='I')
M('E', 1, 'In a mains cable the live and neutral wires carry currents in opposite directions at any instant. What force acts between them?', 'A repulsion', ['An attraction', 'No force', 'A force along the wires'], 'Opposite currents repel.')
N('E', 2, 'Both currents in a pair of parallel wires are doubled and the separation is also doubled. By what factor does the force between them change?', 2 * 2 / 2, None,
  'F ∝ I₁I₂/d: factor = 2 × 2 ÷ 2 = 2.0', ['C1: F ∝ I₁I₂/d'], sig=2, aq='factor')
M('E', 1, 'Two current-carrying wires are electrically neutral overall. What type of force acts between them?', 'A magnetic force', ['An electric force', 'A gravitational force only', 'A nuclear force'], 'The wires have no net charge; the force comes from each current\'s magnetic field.')
N('E', 2, 'Two long parallel wires carry 5.0 A and 2.0 A, and the force per metre between them is 5.0 × 10⁻⁵ N m⁻¹. Calculate their separation. (F/L = µ₀I₁I₂/2πd.)' + MU, GW * 5.0 * 2.0 / 5.0e-5, 'm',
  'd = (µ₀/2π) × I₁I₂ ÷ (F/L) = 2.0 × 10⁻⁷ × 5.0 × 2.0 ÷ 5.0 × 10⁻⁵ = 0.040 m', ['C1: rearranged for d'], sig=2, aq='d')
# medium
N('M', 3, 'Two long parallel wires 0.030 m apart carry 20 A and 15 A. Calculate the force on a 0.50 m length of either wire. (F = µ₀I₁I₂L/2πd.)' + MU, GW * 20 * 15 * 0.50 / 0.030, 'N',
  'F = 2.0 × 10⁻⁷ × 20 × 15 × 0.50 ÷ 0.030 = 1.0 × 10⁻³ N', ['C1: formula', 'C1: substitution'], sig=2, aq='F')
N('M', 3, 'While a car engine starts, the two 0.50 m battery leads, 1.0 cm apart, each carry 200 A in opposite directions. Calculate the force between them. (F = µ₀I₁I₂L/2πd.)' + MU, GW * 200 * 200 * 0.50 / 0.010, 'N',
  'F = 2.0 × 10⁻⁷ × 200 × 200 × 0.50 ÷ 0.010 = 0.40 N, a repulsion', ['C1: substitution', 'B1: repulsion for opposite currents'], sig=2, aq='F')
M('M', 3, 'Three long parallel wires A, B and C lie equally spaced in a plane, with B in the middle. All carry equal currents in the same direction. What is the resultant magnetic force on B?', 'Zero', ['Towards A', 'Towards C', 'Away from the plane'], 'B is attracted equally by A and C, in opposite directions.', ['C1: equal attractions', 'C1: opposite directions cancel'])
N('M', 4, 'Three long parallel wires A, B and C lie in a plane with B midway between them, 0.040 m from each. A carries 10 A and B and C each carry 5.0 A, all in the same direction. Calculate the resultant force per metre on B. (F/L = µ₀I₁I₂/2πd.)' + MU, GW * (10 - 5.0) * 5.0 / 0.040, 'N m⁻¹',
  'Towards A: 2.0 × 10⁻⁷ × 10 × 5.0 ÷ 0.040 = 2.5 × 10⁻⁴ N m⁻¹. Towards C: 2.0 × 10⁻⁷ × 5.0 × 5.0 ÷ 0.040 = 1.25 × 10⁻⁴ N m⁻¹. Resultant = 2.5 × 10⁻⁴ − 1.25 × 10⁻⁴ = 1.25 × 10⁻⁴ N m⁻¹ towards A', ['C1: force from A', 'C1: force from C', 'M1: opposite directions subtract'], aq='F/L')
N('M', 3, 'Two overhead power lines 5.0 m apart each carry 1.0 kA. Calculate the force per metre between them. (F/L = µ₀I₁I₂/2πd.)' + MU, GW * 1000 * 1000 / 5.0, 'N m⁻¹',
  'F/L = 2.0 × 10⁻⁷ × 1000 × 1000 ÷ 5.0 = 0.040 N m⁻¹', ['C1: substitution', 'C1: kA converted'], sig=2, aq='F/L')
M('M', 3, 'The currents in two parallel wires are 3.0 A and 7.0 A. They are swapped, so the first carries 7.0 A and the second 3.0 A. What happens to the force between them?', 'It stays the same', ['It increases', 'It decreases', 'It reverses direction'], 'F depends on the product I₁I₂, which is unchanged.', ['C1: F ∝ I₁I₂', 'C1: product unchanged'])
N('M', 3, 'Two long parallel wires are 0.050 m apart. One carries 10 A, and the force per metre between them is 6.0 × 10⁻⁵ N m⁻¹. Calculate the current in the other wire. (F/L = µ₀I₁I₂/2πd.)' + MU, 6.0e-5 * 0.050 / (GW * 10), 'A',
  'I₂ = (F/L) × d ÷ ((µ₀/2π) × I₁) = 6.0 × 10⁻⁵ × 0.050 ÷ (2.0 × 10⁻⁷ × 10) = 1.5 A', ['C1: rearranged', 'C1: substitution'], sig=2, aq='I₂')
N('M', 4, 'The old definition of the ampere used wires 1.0 m apart. If the force on each metre is measured as 8.0 × 10⁻⁷ N for equal currents, what current flows in each? (F/L = µ₀I²/2πd.)' + MU, sqrt(8.0e-7 / GW), 'A',
  'I² = 8.0 × 10⁻⁷ × 1.0 ÷ 2.0 × 10⁻⁷ = 4.0, so I = √4.0 = 2.0 A', ['C1: equal currents give I²', 'C1: rearranged', 'C1: value'], sig=2, aq='I')
M('M', 3, 'When calculating the force on wire 2 from F = BIL, why is the field of wire 1 used and not the field of wire 2?', 'A wire\'s own field exerts no resultant force on that wire', ['Wire 2 has no field', 'The field of wire 2 is always weaker', 'The two fields are always equal'], 'Only an external field produces a net force on a current.', ['C1: own field no net force', 'C1: use field of the other wire'])
N('M', 3, 'A fixed horizontal wire carries 50 A. A parallel wire directly above it, with a mass of 1.0 × 10⁻³ kg per metre, also carries 50 A in the opposite direction. Calculate the separation at which the upper wire is supported by the magnetic force alone, in cm. (F/L = µ₀I₁I₂/2πd.)' + MU + take('g'), GW * 50 * 50 / (1.0e-3 * g) * 100, 'cm',
  f'Magnetic force per metre = weight per metre: 2.0 × 10⁻⁷ × 50 × 50 ÷ d = 1.0 × 10⁻³ × 9.81, so d = 5.0 × 10⁻⁴ ÷ 9.81 × 10⁻³ = {sf(5e-4 / 9.81e-3)} m. In cm: {sf(5e-4 / 9.81e-3, 4)} × 100 = {sf(5e-4 / 9.81e-3 * 100)}', ['M1: repulsion balances weight', 'C1: rearranged for d'], aq='d')
M('M', 4, 'Two parallel wires carry currents in opposite directions. Using the left-hand rule, why do they repel?', 'At each wire, the field of the other wire combined with its own current gives a force directed away from the other wire', ['Each wire is attracted to the other\'s north pole', 'Opposite currents carry opposite charges', 'The fields cancel between the wires, pulling them apart'], 'Reversing one current reverses the force on it relative to the like-current case.', ['C1: field of other wire', 'C1: left-hand rule', 'C1: force away'])
N('M', 3, 'The separation of two parallel wires is increased from 2.0 cm to 5.0 cm with the currents unchanged. Calculate (new force) ÷ (old force).', 2.0 / 5.0, None,
  'F ∝ 1/d: ratio = 2.0 ÷ 5.0 = 0.40', ['C1: F ∝ 1/d', 'C1: ratio'], sig=2, aq='ratio')
N('M', 3, 'Wire 2 carries 6.0 A, and the force on each metre of it due to a parallel wire 1 is 3.0 × 10⁻⁵ N m⁻¹. Calculate the flux density of wire 1\'s field at wire 2, in µT.', 3.0e-5 / 6.0 * 1e6, 'µT',
  'F/L = BI, so B = 3.0 × 10⁻⁵ ÷ 6.0 = 5.0 × 10⁻⁶ T. In µT: 5.0 × 10⁻⁶ × 10⁶ = 5.0', ['C1: F/L = BI', 'C1: conversion'], sig=2, aq='B')
M('M', 3, 'Why are the busbars in an electrical substation firmly clamped in place?', 'Fault currents can be thousands of amperes, producing very large forces between neighbouring bars', ['To stop them being attracted to the Earth\'s field', 'To keep them cool', 'To stop electric charges building up'], 'F ∝ I₁I₂, so a large fault current gives a very large force.', ['C1: F ∝ I₁I₂', 'C1: large forces in faults'])
N('M', 4, 'Two neighbouring turns of a coil are 2.0 mm apart and each carries 50 A in the same sense. Treating them as parallel wires of length 0.30 m, calculate the force between them. (F = µ₀I₁I₂L/2πd.)' + MU, GW * 50 * 50 * 0.30 / 2.0e-3, 'N',
  'F = 2.0 × 10⁻⁷ × 50 × 50 × 0.30 ÷ 2.0 × 10⁻³ = 0.075 N, an attraction', ['C1: d in m', 'C1: substitution', 'B1: attraction'], sig=2, aq='F')
N('M', 3, 'Two long parallel wires are 4.0 cm apart; wire 1 carries 12 A. The force on each metre of wire 2 is 1.5 × 10⁻⁴ N m⁻¹. Calculate the current in wire 2. (B = µ₀I/2πr.)' + MU, 1.5e-4 / (GW * 12 / 0.040), 'A',
  'Field of the first wire at the second: 2.0 × 10⁻⁷ × 12 ÷ 0.040 = 6.0 × 10⁻⁵ T. I₂ = (F/L) ÷ B₁ = 1.5 × 10⁻⁴ ÷ 6.0 × 10⁻⁵ = 2.5 A', ['C1: B₁ at wire 2', 'C1: I₂ = (F/L)/B₁'], sig=2, aq='I₂')
M('M', 3, 'For two long parallel wires, how does the force depend on the length of wire considered?', 'It is proportional to the length, so the force per metre is the same along the wires', ['It is independent of length', 'It is inversely proportional to the length', 'It depends on the length squared'], 'F = BIL with B the same all along a long wire.', ['C1: F ∝ L', 'C1: constant force per metre'])
N('M', 3, 'Two parallel wires 1.5 m long and 0.10 m apart carry 25 A and 40 A. Calculate the force between them. (F = µ₀I₁I₂L/2πd.)' + MU, GW * 25 * 40 * 1.5 / 0.10, 'N',
  'F = 2.0 × 10⁻⁷ × 25 × 40 × 1.5 ÷ 0.10 = 3.0 × 10⁻³ N', ['C1: formula', 'C1: substitution'], sig=2, aq='F')
# hard
N('H', 6, 'In a current balance, a 0.25 m length of wire is held 3.0 mm above a fixed parallel wire. The same current I flows through both, in opposite directions, and the repulsion is balanced by a 0.10 g mass. (a) Calculate the force between the wires. (b) Write an expression for the force in terms of I. (c) Calculate I. Give only the answer to (c).' + MU + take('g'), sqrt(0.10e-3 * g * 3.0e-3 / (GW * 0.25)), 'A',
  f'(a) F = 0.10 × 10⁻³ × 9.81 = 9.81 × 10⁻⁴ N. (b) F = (µ₀/2π) × I² × L ÷ d. (c) I² = 9.81 × 10⁻⁴ × 3.0 × 10⁻³ ÷ (2.0 × 10⁻⁷ × 0.25) = {sf(9.81e-4 * 3e-3 / (5e-8))}, so I = √{sf(9.81e-4 * 3e-3 / (5e-8), 4)} = {sf(sqrt(9.81e-4 * 3e-3 / 5e-8))} A',
  ['C1: F = mg', 'C1: expression with I²', 'M1: rearranged for I²', 'C1: substitution', 'C1: square root'], aq='I')
N('H', 5, 'Three long parallel wires pass through the corners of an equilateral triangle of side 0.10 m. Each carries 10 A in the same direction. (a) Calculate the force per metre between any two wires. (b) Calculate the resultant force per metre on one wire. (c) State its direction. Give only the answer to (b).' + MU, 2 * GW * 100 / 0.10 * cos(radians(30)), 'N m⁻¹',
  f'(a) F/L = 2.0 × 10⁻⁷ × 10 × 10 ÷ 0.10 = 2.0 × 10⁻⁴ N m⁻¹. (b) The two attractions are at 60° to each other: resultant = 2 × 2.0 × 10⁻⁴ × cos 30° = {sf(4e-4 * cos(radians(30)))} N m⁻¹. (c) Towards the centre of the triangle.',
  ['C1: one pair', 'M1: vector sum at 60°', 'C1: 2F cos 30°', 'B1: towards centre'], aq='F/L')
N('H', 6, 'Three long parallel wires A, B and C lie in a plane. B is 0.040 m from A and 0.060 m from C. A and C each carry 10 A in one direction and B carries 5.0 A in the opposite direction. (a) Explain whether B is attracted or repelled by each of the others. (b) Calculate the force per metre on B due to A and due to C. (c) Calculate the resultant force per metre on B and state its direction. Give only the magnitude from (c).' + MU, GW * 10 * 5.0 / 0.040 - GW * 10 * 5.0 / 0.060, 'N m⁻¹',
  f'(a) Opposite currents repel, so B is repelled by both. (b) From A: 2.0 × 10⁻⁷ × 10 × 5.0 ÷ 0.040 = 2.5 × 10⁻⁴ N m⁻¹, towards C. From C: 2.0 × 10⁻⁷ × 10 × 5.0 ÷ 0.060 = {sf(GW * 50 / 0.06)} N m⁻¹, towards A. (c) Resultant = 2.5 × 10⁻⁴ − {sf(GW * 50 / 0.06, 4)} = {sf(GW * 50 / 0.04 - GW * 50 / 0.06)} N m⁻¹, towards C.',
  ['B1: repelled by both', 'C1: force from A', 'C1: force from C', 'M1: opposite directions subtract', 'B1: direction towards C'], aq='F/L')
N('H', 5, 'A fixed horizontal wire carries 80 A. A parallel wire with a mass of 2.0 g per metre carries 40 A in the opposite direction and floats directly above it. (a) Explain why the upper wire can float. (b) Calculate the height of the upper wire above the lower one, in cm. (F/L = µ₀I₁I₂/2πd.) Give only the answer to (b).' + MU + take('g'), GW * 80 * 40 / (2.0e-3 * g) * 100, 'cm',
  f'(a) Opposite currents repel, so the upper wire is pushed up; it floats where this repulsion equals its weight. (b) 2.0 × 10⁻⁷ × 80 × 40 ÷ d = 2.0 × 10⁻³ × 9.81, so d = 6.4 × 10⁻⁴ ÷ 1.962 × 10⁻² = {sf(6.4e-4 / 1.962e-2)} m. In cm: {sf(6.4e-4 / 1.962e-2, 4)} × 100 = {sf(6.4e-4 / 1.962e-2 * 100)}',
  ['B1: repulsion balances weight', 'C1: weight per metre', 'M1: equation for d', 'C1: value in cm'], aq='d')
N('H', 6, '(a) Use B = µ₀I₁/2πd and F = BI₂L to show that the force between two long parallel wires is F = µ₀I₁I₂L/2πd. (b) Calculate the force between two 0.80 m lengths of wire 0.012 m apart, carrying 4.0 A and 6.0 A. (c) Explain why the forces on the two wires are equal even though the currents differ. Give only the answer to (b).' + MU, GW * 4.0 * 6.0 * 0.80 / 0.012, 'N',
  f'(a) Wire 2 is in field B = µ₀I₁/2πd, so F = BI₂L = µ₀I₁I₂L/2πd. (b) F = 2.0 × 10⁻⁷ × 4.0 × 6.0 × 0.80 ÷ 0.012 = {sf(GW * 24 * 0.8 / 0.012)} N. (c) The expression is symmetric in I₁ and I₂, as Newton\'s third law requires.',
  ['M1: field of wire 1 at wire 2', 'B1: F = BI₂L gives the result', 'C1: substitution', 'C1: value', 'B1: symmetric, Newton\'s third law'], aq='F')
N('H', 5, 'In a substation, two parallel busbars 2.0 m long and 0.30 m apart carry a fault current of 20 kA in opposite directions. (a) Calculate the force between them. (b) Explain why such a force is dangerous. Give only the answer to (a).' + MU, GW * 20e3 * 20e3 * 2.0 / 0.30, 'N',
  f'(a) F = 2.0 × 10⁻⁷ × 20 × 10³ × 20 × 10³ × 2.0 ÷ 0.30 = {sf(GW * 4e8 * 2 / 0.3)} N. (b) A sudden force of several hundred newtons could bend or break the bars and their supports.',
  ['C1: kA converted', 'C1: formula', 'C1: value', 'B1: mechanical damage'], aq='F')
N('H', 6, 'Two long parallel wires carry equal currents I. The force per metre is measured at different separations d: d/cm = 1.0, 2.0, 4.0, 8.0 and (F/L)/10⁻⁴ N m⁻¹ = 8.0, 4.0, 2.0, 1.0. (a) Show that F/L is inversely proportional to d. (b) Calculate (F/L) × d. (c) Use F/L = µ₀I²/2πd to find I. Give only the answer to (c).' + MU, sqrt(8.0e-4 * 0.010 / GW), 'A',
  f'(a) (F/L) × d is the same for every reading, so F/L ∝ 1/d. (b) (F/L) × d = 8.0 × 10⁻⁴ × 0.010 = 8.0 × 10⁻⁶ N. (c) I² = 8.0 × 10⁻⁶ ÷ 2.0 × 10⁻⁷ = 40, so I = √40 = {sf(sqrt(40))} A',
  ['C1: product calculated', 'B1: constant', 'M1: (F/L)d = (µ₀/2π)I²', 'C1: I²', 'C1: I'], aq='I')
N('H', 5, 'A wire with a mass of 5.0 g per metre carries 20 A and lies 1.0 cm from a parallel wire also carrying 20 A. (a) Calculate the magnetic force per metre between the wires. (b) Calculate the weight per metre of the first wire. (c) Calculate (magnetic force) ÷ (weight). (F/L = µ₀I₁I₂/2πd.) Give only the answer to (c).' + MU + take('g'), (GW * 400 / 0.010) / (5.0e-3 * g), None,
  f'(a) F/L = 2.0 × 10⁻⁷ × 20 × 20 ÷ 0.010 = 8.0 × 10⁻³ N m⁻¹. (b) W/L = 5.0 × 10⁻³ × 9.81 = {sf(5e-3 * 9.81)} N m⁻¹. (c) Ratio = 8.0 × 10⁻³ ÷ {sf(5e-3 * 9.81, 4)} = {sf(8e-3 / (5e-3 * 9.81))}',
  ['C1: magnetic force per metre', 'C1: weight per metre', 'C1: ratio', 'B1: units consistent'], aq='ratio')
N('H', 5, 'Two parallel beams of electrons move in the same direction at speed v. The magnetic attraction between them is smaller than their electric repulsion by a factor of v²/c². (a) Explain why the beams attract magnetically. (b) Calculate (magnetic force) ÷ (electric force) when v = 3.0 × 10⁷ m s⁻¹. (c) State what this implies for the beams. Give only the answer to (b).' + take('c'), (3.0e7 / 3.00e8) ** 2, None,
  '(a) Moving charges are currents; parallel currents in the same direction attract. (b) Ratio = (3.0 × 10⁷ ÷ 3.00 × 10⁸)² = 0.010. (c) The electric repulsion dominates, so the beams spread apart.',
  ['B1: beams are parallel currents', 'C1: v/c', 'C1: ratio', 'B1: beams diverge'], sig=2, aq='ratio')

# ═════════════════════════ 24.7 Relating SI units (17/17/10) ═════════════════════════
lesson('24.7')
M('E', 1, 'What are the SI base units of the newton?', 'kg m s⁻²', ['kg m² s⁻²', 'kg m s⁻¹', 'kg s⁻²'], 'F = ma, so the newton is kg × m s⁻² = kg m s⁻².')
M('E', 1, 'What are the SI base units of the coulomb?', 'A s', ['A s⁻¹', 'A', 'J V⁻¹ s'], 'Q = It, so one coulomb is one ampere for one second: A s.')
M('E', 1, 'Express the volt in SI base units.', 'kg m² s⁻³ A⁻¹', ['kg m² s⁻² A⁻¹', 'kg m s⁻³ A⁻¹', 'kg m² s⁻³ A'], 'V = W/Q = (kg m² s⁻²) ÷ (A s).')
M('E', 1, 'Write the ohm in terms of the SI base units kg, m, s and A.', 'kg m² s⁻³ A⁻²', ['kg m² s⁻³ A⁻¹', 'kg m² s⁻² A⁻²', 'kg m s⁻³ A⁻²'], 'R = V/I: (kg m² s⁻³ A⁻¹) ÷ A.')
M('E', 1, 'Which of these is an SI base quantity?', 'Electric current', ['Electric charge', 'Potential difference', 'Magnetic flux density'], 'The ampere is a base unit; the coulomb, volt and tesla are derived.')
M('E', 1, 'The constant µ₀ has the unit T m A⁻¹. Which is an equivalent unit?', 'N A⁻²', ['N A⁻¹', 'N m A⁻¹', 'A² N⁻¹'], 'T = N A⁻¹ m⁻¹, so T m A⁻¹ = N A⁻².')
M('E', 1, 'Which unit is equivalent to the unit of ε₀, F m⁻¹?', 'C² N⁻¹ m⁻²', ['C N⁻¹ m⁻¹', 'N C⁻² m²', 'C² N m⁻²'], 'F = C V⁻¹ and V = N m C⁻¹, so F m⁻¹ = C² N⁻¹ m⁻².')
N('E', 2, 'A wire 0.30 m long carrying 4.0 A at right angles to a field feels a force of 0.48 N. Calculate the flux density in N A⁻¹ m⁻¹ (that is, in tesla).', 0.48 / (4.0 * 0.30), 'T',
  'B = F/(IL) = 0.48 ÷ (4.0 × 0.30) = 0.40 N A⁻¹ m⁻¹ = 0.40 T', ['C1: B = F/(IL)'], sig=2, aq='B')
M('E', 1, 'Which unit is equivalent to the tesla?', 'V s m⁻²', ['V s⁻¹ m²', 'V m s⁻¹', 'A m⁻²'], 'T = Wb m⁻², and 1 Wb = 1 V s.')
M('E', 1, 'Which unit is equivalent to the weber?', 'V s', ['V s⁻¹', 'A s', 'J A'], 'An e.m.f. of 1 V is induced when the flux linkage changes at 1 Wb s⁻¹, so Wb = V s.')
M('E', 1, 'Which equation is homogeneous in SI base units?', 'F = BIL', ['F = BI/L', 'F = BL/I', 'F = IL/B'], 'B in kg s⁻² A⁻¹ times A times m gives kg m s⁻², the newton.')
N('E', 2, 'Express an energy of 1.0 kW h in joules.', 1000 * 3600, 'J',
  'E = Pt = 1000 × 3600 = 3.6 × 10⁶ J', ['C1: kW → W and h → s'], sig=2, aq='E')
M('E', 1, 'Which value is equal to 50 µT?', '5.0 × 10⁻⁵ T', ['5.0 × 10⁻³ T', '5.0 × 10⁻⁶ T', '50 × 10⁻³ T'], 'µ means 10⁻⁶: 50 × 10⁻⁶ = 5.0 × 10⁻⁵.')
N('E', 1, 'Express a flux density of 0.035 T in mT.', 35, 'mT', 'B = 0.035 × 1000 = 35 mT', [], sig=2, aq='B')
M('E', 1, 'What is the unit of BQv, where B is flux density, Q charge and v velocity?', 'N', ['J', 'T', 'W'], 'BQv is the magnetic force on a moving charge.')
M('E', 1, 'What is the unit of the product RC of a resistance and a capacitance?', 's', ['Ω F', 'C', 'A s⁻¹'], 'Ω F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = s.')
N('E', 2, 'The speed of light in a vacuum is given by c = 1/√(µ₀ε₀). Calculate c using µ₀ = 4π × 10⁻⁷ T m A⁻¹ and ε₀ = 8.85 × 10⁻¹² F m⁻¹.', 1 / sqrt(MU0 * 8.85e-12), 'm s⁻¹',
  f'c = 1 ÷ √(4π × 10⁻⁷ × 8.85 × 10⁻¹²) = {sf(1 / sqrt(MU0 * 8.85e-12))} m s⁻¹', ['C1: substitution'], aq='c')
# medium
M('M', 3, 'What are the SI base units of the farad?', 'A² s⁴ kg⁻¹ m⁻²', ['A s³ kg⁻¹ m⁻²', 'A² s⁴ kg m²', 'A² s³ kg⁻¹ m⁻²'], 'F = C V⁻¹ = (A s) ÷ (kg m² s⁻³ A⁻¹).', ['C1: C = A s', 'C1: divide by volt in base units'])
M('M', 3, 'Show that µ₀I/2πr has the unit of flux density. Which line of working is correct?', '(N A⁻²)(A) ÷ m = N A⁻¹ m⁻¹ = T', ['(N A⁻²)(A) × m = N m A⁻¹ = T', '(T m A⁻¹)(A) × m = T m²', '(N A⁻¹)(A) ÷ m = N m⁻¹'], 'µ₀ is in N A⁻²; multiply by A and divide by m to get T.', ['C1: µ₀ in N A⁻²', 'C1: result in T'])
M('M', 3, 'Which unit is equivalent to T m² s⁻¹?', 'V', ['A', 'W', 'C'], 'T m² = Wb, and Wb s⁻¹ = V.', ['C1: T m² = Wb', 'C1: Wb s⁻¹ = V'])
M('M', 4, 'To check that F = BQv is homogeneous, B is written in base units. Which is the correct check?', '(kg s⁻² A⁻¹)(A s)(m s⁻¹) = kg m s⁻²', ['(kg s⁻² A)(A s)(m s⁻¹) = kg m s⁻²', '(kg s⁻² A⁻¹)(A s⁻¹)(m s⁻¹) = kg m s⁻²', '(kg s⁻² A⁻¹)(A s)(m s) = kg m s⁻²'], 'B = kg s⁻² A⁻¹, Q = A s, v = m s⁻¹; the product is the newton.', ['C1: B in base units', 'C1: Q = A s', 'C1: result kg m s⁻²'])
N('M', 3, 'An old textbook gives a magnet\'s field as 450 gauss, where 1 gauss = 1.0 × 10⁻⁴ T. Express this in tesla.', 450 * 1.0e-4, 'T',
  'B = 450 × 1.0 × 10⁻⁴ = 0.045 T', ['C1: conversion factor', 'C1: value'], sig=2, aq='B')
N('M', 3, 'The Earth\'s field is often quoted as 0.50 gauss, where 1 gauss = 1.0 × 10⁻⁴ T. Express this in µT.', 0.50 * 1.0e-4 * 1e6, 'µT',
  'B = 0.50 × 1.0 × 10⁻⁴ = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50', ['C1: to tesla', 'C1: to µT'], sig=2, aq='B')
M('M', 3, 'Which quantity has the SI base units kg s⁻² A⁻¹?', 'Magnetic flux density', ['Magnetic flux', 'Electric field strength', 'Potential difference'], 'T = N A⁻¹ m⁻¹ = kg m s⁻² A⁻¹ m⁻¹.', ['C1: T = N A⁻¹ m⁻¹', 'C1: base units'])
N('M', 4, 'The energy stored per unit volume in a magnetic field is u = B²/2µ₀. Calculate u for B = 1.0 T, and give its unit.', 1.0 ** 2 / (2 * MU0), 'J m⁻³',
  f'u = 1.0² ÷ (2 × 4π × 10⁻⁷) = {sf(1 / (2 * MU0))} J m⁻³', ['C1: substitution', 'C1: value', 'B1: unit J m⁻³'], aq='u')
M('M', 3, 'What is the unit of B²/µ₀?', 'J m⁻³ (equivalent to Pa)', ['J m⁻²', 'N m⁻¹', 'W m⁻²'], 'T² ÷ (N A⁻²) = (N A⁻¹ m⁻¹)² × A² N⁻¹ = N m⁻² = J m⁻³.', ['C1: T in N A⁻¹ m⁻¹', 'C1: simplify to N m⁻²'])
N('M', 3, 'The ampere used to be defined from the force of 2.0 × 10⁻⁷ N per metre between two long parallel wires 1.0 m apart, each carrying 1.0 A. Use F/L = µ₀I₁I₂/2πd to calculate µ₀, in units of 10⁻⁶ T m A⁻¹.', 2 * pi * 2.0e-7 * 1.0 / (1.0 * 1.0), '10⁻⁶ T m A⁻¹',
  f'µ₀ = 2πd(F/L) ÷ (I₁I₂) = 2π × 1.0 × 2.0 × 10⁻⁷ ÷ (1.0 × 1.0) = {sf(2 * pi * 2e-7)} T m A⁻¹', ['C1: rearranged for µ₀', 'C1: substitution'], aq='µ₀')
M('M', 3, 'Which is a correct unit for flux linkage NΦ?', 'Wb (sometimes written Wb-turns)', ['T', 'Wb m⁻²', 'T m'], 'N is a pure number, so NΦ has the unit of flux.', ['C1: N dimensionless', 'C1: unit Wb'])
N('M', 3, 'A field of 3.0 mT passes at right angles through an area of 4.0 cm². Calculate the flux, in µWb.', 3.0e-3 * 4.0e-4 * 1e6, 'µWb',
  'Φ = BA = 3.0 × 10⁻³ × 4.0 × 10⁻⁴ = 1.2 × 10⁻⁶ Wb. In µWb: 1.2 × 10⁻⁶ × 10⁶ = 1.2', ['C1: cm² to m²', 'C1: Φ = BA'], sig=2, aq='Φ')
M('M', 4, 'Which expression has the unit of speed, m s⁻¹?', 'E/B, electric field strength divided by magnetic flux density', ['B/E', 'EB', 'E/B²'], '(V m⁻¹) ÷ (V s m⁻²) = m s⁻¹.', ['C1: E in V m⁻¹', 'C1: T in V s m⁻²', 'C1: ratio m s⁻¹'])
N('M', 3, 'Show that E/B has the unit m s⁻¹, then evaluate it for E = 3.0 × 10⁴ V m⁻¹ and B = 0.060 T.', 3.0e4 / 0.060, 'm s⁻¹',
  'V m⁻¹ ÷ (V s m⁻²) = m s⁻¹. E/B = 3.0 × 10⁴ ÷ 0.060 = 5.0 × 10⁵ m s⁻¹', ['B1: units shown', 'C1: value'], sig=2, aq='E/B')
M('M', 3, 'What is the product of the units ohm and farad equal to?', 'The second', ['The coulomb', 'The ampere', 'The volt'], 'Ω F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = s.', ['C1: write in V, A, C', 'C1: simplify'])
N('M', 3, 'A field of 0.20 Wb m⁻² acts at right angles to 15 cm of wire carrying 2.0 A. Calculate the force on the wire.', 0.20 * 2.0 * 0.15, 'N',
  '1 Wb m⁻² = 1 T. F = BIL = 0.20 × 2.0 × 0.15 = 0.060 N', ['B1: Wb m⁻² = T', 'C1: F = BIL'], sig=2, aq='F')
M('M', 3, 'Which pair of quantities have the same SI base units?', 'Work and the moment of a force', ['Power and energy', 'Force and momentum', 'Charge and current'], 'Both are N m = kg m² s⁻², although work is usually given in joules.', ['C1: both N m', 'C1: same base units'])
# hard
N('H', 5, '(a) Show that the tesla is equivalent to kg s⁻² A⁻¹. (b) Show that µ₀I/2πr has the same units. (c) Calculate the flux density 0.030 m from a long wire carrying 15 A, in µT. (B = µ₀I/2πr.) Give only the answer to (c).' + MU, GW * 15 / 0.030 * 1e6, 'µT',
  '(a) T = N A⁻¹ m⁻¹ = kg m s⁻² A⁻¹ m⁻¹ = kg s⁻² A⁻¹. (b) µ₀ in N A⁻² = kg m s⁻² A⁻²; × A ÷ m gives kg s⁻² A⁻¹. (c) B = 2.0 × 10⁻⁷ × 15 ÷ 0.030 = 1.0 × 10⁻⁴ T. In µT: 1.0 × 10⁻⁴ × 10⁶ = 100',
  ['B1: T in base units', 'B1: µ₀I/2πr in base units', 'C1: B', 'C1: conversion'], sig=2, aq='B')
N('H', 5, '(a) Show that Wb s⁻¹ is equivalent to the volt. (b) The flux linkage of a coil changes by 0.060 Wb in 0.020 s. Calculate the average rate of change of flux linkage and state its unit. Give only the answer to (b).', 0.060 / 0.020, 'V',
  '(a) Wb = T m² = (kg s⁻² A⁻¹)(m²) = kg m² s⁻² A⁻¹; ÷ s gives kg m² s⁻³ A⁻¹, which is the volt. (b) Rate = 0.060 ÷ 0.020 = 3.0 Wb s⁻¹ = 3.0 V',
  ['B1: Wb in base units', 'B1: matches the volt', 'C1: rate', 'C1: unit V'], sig=2, aq='rate')
N('H', 5, '(a) Show that 1/√(µ₀ε₀) has the unit m s⁻¹. (b) Calculate its value, using µ₀ = 4π × 10⁻⁷ T m A⁻¹ and ε₀ = 8.85 × 10⁻¹² F m⁻¹. (c) Calculate the time for light to travel 1.0 km in a vacuum, in µs. Give only the answer to (c).', 1000 * sqrt(MU0 * 8.85e-12) * 1e6, 'µs',
  f'(a) µ₀ε₀ has units (N A⁻²)(C² N⁻¹ m⁻²) = (A s)² A⁻² m⁻² = s² m⁻², so 1/√(µ₀ε₀) is in m s⁻¹. (b) c = 1 ÷ √(4π × 10⁻⁷ × 8.85 × 10⁻¹²) = {sf(1 / sqrt(MU0 * 8.85e-12))} m s⁻¹. (c) t = 1000 ÷ {sf(1 / sqrt(MU0 * 8.85e-12), 4)} = {sf(1000 * sqrt(MU0 * 8.85e-12))} s. In µs: {sf(1000 * sqrt(MU0 * 8.85e-12), 4)} × 10⁶ = {sf(1000 * sqrt(MU0 * 8.85e-12) * 1e6)}',
  ['B1: units of µ₀ε₀', 'C1: c', 'C1: t = d/c', 'C1: conversion to µs'], aq='t')
N('H', 5, 'The magnetic pressure exerted by a field is p = B²/2µ₀. (a) Show that B²/µ₀ has the unit Pa. (b) Calculate p for B = 0.50 T. (c) Compare it with atmospheric pressure, 1.0 × 10⁵ Pa. Give only the answer to (b).', 0.50 ** 2 / (2 * MU0), 'Pa',
  f'(a) T² ÷ (N A⁻²) = (N² A⁻² m⁻²) × (A² N⁻¹) = N m⁻² = Pa. (b) p = 0.50² ÷ (2 × 4π × 10⁻⁷) = {sf(0.25 / (2 * MU0))} Pa. (c) It is about the same as atmospheric pressure.',
  ['B1: units shown', 'C1: substitution', 'C1: value', 'B1: comparison'], aq='p')
N('H', 5, '(a) Use F = BQv to show that 1 T = 1 N s C⁻¹ m⁻¹. (b) Calculate the magnetic force on an electron moving at 2.0 × 10⁷ m s⁻¹ at right angles to a field of 5.0 mT, in units of 10⁻¹⁴ N. Give only the answer to (b).' + take('e'), QE * 2.0e7 * 5.0e-3, '10⁻¹⁴ N',
  f'(a) B = F/(Qv): N ÷ (C × m s⁻¹) = N s C⁻¹ m⁻¹. (b) F = BQv = 5.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 2.0 × 10⁷ = {sf(5e-3 * QE * 2e7)} N',
  ['B1: rearranged F = BQv', 'B1: unit shown', 'C1: F = BQv', 'C1: value'], sig=2, aq='F')
N('H', 6, 'A charged particle moving at right angles to a uniform magnetic field follows a circle of radius r = mv/BQ. (a) Show that mv/BQ has the unit of length. (b) Calculate r for a proton moving at 1.0 × 10⁶ m s⁻¹ in a field of 0.50 T, in cm. Give only the answer to (b).' + take('mp', 'e'), MP * 1.0e6 / (0.50 * QE) * 100, 'cm',
  f'(a) (kg m s⁻¹) ÷ (kg s⁻² A⁻¹ × A s) = (kg m s⁻¹) ÷ (kg s⁻¹) = m. (b) r = 1.67 × 10⁻²⁷ × 1.0 × 10⁶ ÷ (0.50 × 1.60 × 10⁻¹⁹) = {sf(MP * 1e6 / (0.5 * QE))} m. In cm: {sf(MP * 1e6 / (0.5 * QE), 4)} × 100 = {sf(MP * 1e6 / (0.5 * QE) * 100)}',
  ['B1: momentum in base units', 'B1: BQ in base units', 'B1: result m', 'C1: substitution', 'C1: conversion'], aq='r')
N('H', 5, '(a) Show that µ₀I₁I₂L/2πd has the unit of force. (b) Calculate the force between two 1.0 m lengths of parallel wire 0.50 m apart, each carrying 2.0 A, in µN. (F = µ₀I₁I₂L/2πd.) Give only the answer to (b).' + MU, GW * 2.0 * 2.0 * 1.0 / 0.50 * 1e6, 'µN',
  '(a) (N A⁻²)(A)(A)(m) ÷ m = N. (b) F = 2.0 × 10⁻⁷ × 2.0 × 2.0 × 1.0 ÷ 0.50 = 1.6 × 10⁻⁶ N. In µN: 1.6 × 10⁻⁶ × 10⁶ = 1.6',
  ['B1: units reduce to N', 'C1: substitution', 'C1: value', 'C1: conversion'], sig=2, aq='F')
N('H', 5, 'A charged particle in a uniform magnetic field circles with frequency f = BQ/2πm. (a) Show that BQ/m has the unit s⁻¹. (b) Calculate f for a proton in a field of 1.5 T, in MHz. Give only the answer to (b).' + take('e', 'mp'), 1.5 * QE / (2 * pi * MP) / 1e6, 'MHz',
  f'(a) (kg s⁻² A⁻¹)(A s) ÷ kg = s⁻¹. (b) f = 1.5 × 1.60 × 10⁻¹⁹ ÷ (2π × 1.67 × 10⁻²⁷) = {sf(1.5 * QE / (2 * pi * MP))} Hz. In MHz: {sf(1.5 * QE / (2 * pi * MP), 4)} ÷ 10⁶ = {sf(1.5 * QE / (2 * pi * MP) / 1e6)}',
  ['B1: units shown', 'C1: substitution', 'C1: value in Hz', 'C1: conversion to MHz'], aq='f')
N('H', 6, 'The energy stored in the field inside a solenoid is W = B²V/2µ₀, where V is the volume. (a) Show that this expression has the unit of energy. (b) Calculate W for B = 0.20 T in a volume of 1.0 × 10⁻³ m³. Give only the answer to (b).', 0.20 ** 2 * 1.0e-3 / (2 * MU0), 'J',
  f'(a) B²/µ₀ is in J m⁻³; multiplied by m³ gives J. (b) W = 0.20² × 1.0 × 10⁻³ ÷ (2 × 4π × 10⁻⁷) = {sf(0.04e-3 / (2 * MU0))} J',
  ['B1: B²/µ₀ in J m⁻³', 'B1: × volume gives J', 'C1: substitution', 'C1: value', 'C1: µ₀ value used'], aq='W')
N('H', 5, '(a) From C = ε₀A/d, show that ε₀ can be given in F m⁻¹. (b) Calculate µ₀ε₀c², using µ₀ = 4π × 10⁻⁷ T m A⁻¹, ε₀ = 8.85 × 10⁻¹² F m⁻¹ and c = 3.00 × 10⁸ m s⁻¹, and comment on the result. Give only the value from (b).', MU0 * 8.85e-12 * 3.00e8 ** 2, None,
  f'(a) ε₀ = Cd/A has unit F m ÷ m² = F m⁻¹. (b) µ₀ε₀c² = 4π × 10⁻⁷ × 8.85 × 10⁻¹² × (3.00 × 10⁸)² = {sf(MU0 * 8.85e-12 * 9e16)}: a pure number equal to 1, because c = 1/√(µ₀ε₀).',
  ['B1: ε₀ = Cd/A', 'C1: substitution', 'C1: value', 'B1: dimensionless, equals 1'], aq='µ₀ε₀c²')

# ═════════════════════════ 24.8 Comparing forces in magnetic, electric and gravitational fields (17/19/8) ═════════════════════════
lesson('24.8')
M('E', 1, 'Which force on a charged particle depends on the particle\'s velocity?', 'The magnetic force', ['The electric force', 'The gravitational force', 'None of them'], 'F = BQv sin θ; the electric and gravitational forces do not depend on velocity.')
M('E', 1, 'How is the magnetic force on a moving charged particle directed relative to its velocity?', 'At right angles to the velocity', ['Along the velocity', 'Opposite to the velocity', 'At 45° to the velocity'], 'The force is perpendicular to both v and B.')
N('E', 2, 'A proton moves at 2.0 × 10⁶ m s⁻¹ at right angles to a field of 0.30 T. Calculate the magnetic force on it, in units of 10⁻¹⁴ N.' + take('e'), 0.30 * QE * 2.0e6, '10⁻¹⁴ N',
  f'F = BQv = 0.30 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁶ = {sf(0.3 * QE * 2e6)} N', ['C1: F = BQv'], sig=2, aq='F')
N('E', 2, 'Calculate the electric force on a proton in a field of 5.0 × 10⁴ V m⁻¹, in units of 10⁻¹⁵ N.' + take('e'), QE * 5.0e4, '10⁻¹⁵ N',
  f'F = EQ = 5.0 × 10⁴ × 1.60 × 10⁻¹⁹ = {sf(5e4 * QE)} N', ['C1: F = EQ'], sig=2, aq='F')
N('E', 2, 'Calculate the gravitational force on a proton at the Earth\'s surface, in units of 10⁻²⁶ N.' + take('mp', 'g'), MP * g, '10⁻²⁶ N',
  f'F = mg = 1.67 × 10⁻²⁷ × 9.81 = {sf(MP * 9.81)} N', ['C1: F = mg'], aq='F')
M('E', 1, 'Which field exerts a force on an uncharged particle?', 'A gravitational field only', ['An electric field only', 'A magnetic field only', 'All three fields'], 'Electric and magnetic forces need charge; gravity needs only mass.')
M('E', 1, 'How does the force of a uniform electric field on a charged particle depend on its motion?', 'It is the same whether the particle is at rest or moving', ['It is zero when the particle moves', 'It increases with speed', 'It acts only on moving particles'], 'F = EQ does not involve velocity.')
N('E', 2, 'Calculate the weight of an electron at the Earth\'s surface, in units of 10⁻³⁰ N.' + take('me', 'g'), ME * g, '10⁻³⁰ N',
  f'W = mg = 9.11 × 10⁻³¹ × 9.81 = {sf(ME * 9.81)} N', ['C1: W = mg'], aq='W')
M('E', 1, 'A charged particle moves through a region containing only a uniform magnetic field. What happens to its speed?', 'It stays constant', ['It increases', 'It decreases', 'It falls to zero'], 'The magnetic force is always perpendicular to the velocity, so it does no work.')
N('E', 2, 'An oil droplet of mass 1.0 × 10⁻¹⁴ kg carries a charge of 3.2 × 10⁻¹⁹ C. Calculate the vertical electric field strength that balances its weight.' + take('g'), 1.0e-14 * g / 3.2e-19, 'V m⁻¹',
  f'EQ = mg, so E = 1.0 × 10⁻¹⁴ × 9.81 ÷ 3.2 × 10⁻¹⁹ = {sf(1e-14 * 9.81 / 3.2e-19)} V m⁻¹', ['C1: EQ = mg'], aq='E')
M('E', 1, 'A charged particle moves parallel to the field lines of a uniform magnetic field. What force does the magnetic field exert on it?', 'None', ['A force along its motion', 'A force opposite to its motion', 'A force at right angles to its motion'], 'F = BQv sin θ, and θ = 0.')
N('E', 2, 'An electron crosses a 0.20 T field at 30° to the field lines with speed 1.0 × 10⁷ m s⁻¹. Find the magnetic force on it, in units of 10⁻¹³ N.' + take('e'), 0.20 * QE * 1.0e7 * sin(radians(30)), '10⁻¹³ N',
  f'F = BQv sin θ = 0.20 × 1.60 × 10⁻¹⁹ × 1.0 × 10⁷ × sin 30° = {sf(0.2 * QE * 1e7 * 0.5)} N', ['C1: F = BQv sin θ'], sig=2, aq='F')
M('E', 1, 'Which list correctly gives the units of gravitational field strength, electric field strength and magnetic flux density?', 'N kg⁻¹, N C⁻¹, N A⁻¹ m⁻¹', ['N kg, N C, N A m', 'kg N⁻¹, C N⁻¹, A m N⁻¹', 'J kg⁻¹, J C⁻¹, J A⁻¹'], 'g = F/m, E = F/Q and B = F/(IL).')
N('E', 2, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at right angles to a magnetic field of 0.010 T, in a region that also has an electric field of 1.0 × 10⁴ V m⁻¹. Calculate (electric force) ÷ (magnetic force).', 1.0e4 / (0.010 * 2.0e6), None,
  'eE ÷ (eBv) = E/(Bv) = 1.0 × 10⁴ ÷ (0.010 × 2.0 × 10⁶) = 0.50', ['C1: ratio E/(Bv)'], sig=2, aq='ratio')
M('E', 1, 'In which direction is the electric force on a negative charge?', 'Opposite to the electric field', ['Along the electric field', 'At right angles to the electric field', 'Towards the nearest earthed object'], 'The field direction is defined by the force on a positive charge.')
N('E', 1, 'The gravitational field strength on the Moon is 1.6 N kg⁻¹. Calculate the weight of a 2.0 kg mass there.', 1.6 * 2.0, 'N', 'W = mg = 2.0 × 1.6 = 3.2 N', [], sig=2, aq='W')
M('E', 1, 'For which fields does the force on a particle act along the field lines?', 'Electric and gravitational fields', ['Magnetic fields only', 'All three fields', 'None of the three fields'], 'The magnetic force is perpendicular to the field lines.')
# medium
N('M', 3, 'A proton moves at 1.0 × 10⁵ m s⁻¹ at right angles to the Earth\'s field of 5.0 × 10⁻⁵ T. Calculate (magnetic force) ÷ (weight).' + take('e', 'mp', 'g'), QE * 1.0e5 * 5.0e-5 / (MP * g), None,
  f'F_B = 5.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 1.0 × 10⁵ = {sf(5e-5 * QE * 1e5)} N. W = 1.67 × 10⁻²⁷ × 9.81 = {sf(MP * 9.81)} N. Ratio = {sf(5e-5 * QE * 1e5, 4)} ÷ {sf(MP * 9.81, 4)} = {sf(5e-5 * QE * 1e5 / (MP * 9.81))}', ['C1: F = BQv', 'C1: W = mg'], aq='ratio')
N('M', 3, 'At what speed, moving at right angles to the Earth\'s field of 5.0 × 10⁻⁵ T, would the magnetic force on an electron equal its weight?' + take('me', 'g', 'e'), ME * g / (QE * 5.0e-5), 'm s⁻¹',
  f'BQv = mg, so v = 9.11 × 10⁻³¹ × 9.81 ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻⁵) = {sf(ME * 9.81 / (QE * 5e-5))} m s⁻¹', ['M1: BQv = mg', 'C1: substitution'], aq='v')
M('M', 3, 'A proton moves through a region containing both electric and magnetic fields. As its speed changes, which force changes in size?', 'Only the magnetic force', ['Only the electric force', 'Both forces', 'Neither force'], 'F_B = BQv depends on v; F_E = EQ does not.', ['C1: F_B ∝ v', 'C1: F_E independent of v'])
N('M', 4, 'A proton moves 0.020 m along the direction of a uniform electric field of 3.0 × 10⁴ V m⁻¹, while a magnetic field also acts. Calculate the work done on the proton by the electric field, in units of 10⁻¹⁷ J.' + take('e'), QE * 3.0e4 * 0.020, '10⁻¹⁷ J',
  f'W = EQd = 3.0 × 10⁴ × 1.60 × 10⁻¹⁹ × 0.020 = {sf(3e4 * QE * 0.02)} J. The magnetic force does no work, because it is always perpendicular to the motion.', ['C1: F = EQ', 'C1: W = Fd', 'B1: magnetic force does no work'], sig=2, aq='W')
N('M', 3, 'Calculate (acceleration of an electron in an electric field of 1.0 × 10³ V m⁻¹) ÷ (acceleration of free fall, 9.81 m s⁻²).' + take('e', 'me'), QE * 1.0e3 / ME / 9.81, None,
  f'a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10³ ÷ 9.11 × 10⁻³¹ = {sf(QE * 1e3 / ME)} m s⁻². Ratio = {sf(QE * 1e3 / ME, 4)} ÷ 9.81 = {sf(QE * 1e3 / ME / 9.81)}', ['C1: a = eE/m', 'C1: ratio'], aq='ratio')
M('M', 3, 'A charged particle enters a uniform field moving at right angles to the field lines. Which row gives the shape of its path?', 'Electric field: parabola. Magnetic field: circular arc. Gravitational field: parabola.', ['Electric field: circle. Magnetic field: parabola. Gravitational field: parabola.', 'All three: parabolas', 'All three: circles'], 'A constant force (E or g) gives projectile motion; a magnetic force perpendicular to v gives circular motion.', ['C1: constant force gives parabola', 'C1: perpendicular force gives circle'])
N('M', 3, 'In a cloud chamber, an α-particle (charge 2e) travelling at 1.5 × 10⁷ m s⁻¹ crosses a 1.2 T field at right angles. What magnetic force acts on it, in units of 10⁻¹² N?' + take('e'), 2 * QE * 1.5e7 * 1.2, '10⁻¹² N',
  f'F = BQv = 1.2 × 2 × 1.60 × 10⁻¹⁹ × 1.5 × 10⁷ = {sf(1.2 * 2 * QE * 1.5e7)} N', ['C1: Q = 2e', 'C1: F = BQv'], aq='F')
N('M', 4, 'An electron moves at 4.0 × 10⁶ m s⁻¹ at right angles to a magnetic field of 2.5 mT. Calculate the electric field strength needed to produce an equal and opposite force.', 4.0e6 * 2.5e-3, 'V m⁻¹',
  'eE = eBv, so E = Bv = 2.5 × 10⁻³ × 4.0 × 10⁶ = 1.0 × 10⁴ V m⁻¹', ['M1: eE = eBv', 'C1: E = Bv', 'C1: substitution'], sig=2, aq='E')
M('M', 4, 'A charged dust grain moves through a region with gravitational, electric and magnetic fields. Which of these fields can change its kinetic energy?', 'The gravitational and electric fields only', ['The magnetic field only', 'All three fields', 'The electric field only'], 'The magnetic force is perpendicular to the velocity, so it does no work.', ['C1: work needs force along motion', 'C1: magnetic force perpendicular', 'C1: g and E can do work'])
N('M', 3, 'A proton and an electron move at the same speed at right angles to the same magnetic field. Calculate (acceleration of proton) ÷ (acceleration of electron).' + take('me', 'mp'), ME / MP, None,
  f'The forces are equal in size (same Q, v and B), so a ∝ 1/m: ratio = 9.11 × 10⁻³¹ ÷ 1.67 × 10⁻²⁷ = {sf(ME / MP)}', ['C1: equal forces', 'C1: a ∝ 1/m'], aq='ratio')
N('M', 3, 'A droplet of mass 2.0 × 10⁻¹² kg carries a charge of 1.6 × 10⁻¹⁷ C in an electric field of 2.0 × 10³ V m⁻¹. Calculate (electric force) ÷ (weight).' + take('g'), 1.6e-17 * 2.0e3 / (2.0e-12 * g), None,
  f'F_E = 2.0 × 10³ × 1.6 × 10⁻¹⁷ = 3.2 × 10⁻¹⁴ N. W = 2.0 × 10⁻¹² × 9.81 = {sf(2e-12 * 9.81)} N. Ratio = 3.2 × 10⁻¹⁴ ÷ {sf(2e-12 * 9.81, 4)} = {sf(3.2e-14 / (2e-12 * 9.81))}', ['C1: F = EQ', 'C1: W = mg'], aq='ratio')
M('M', 3, 'Which statement about the three types of force is correct?', 'The directions of the electric and magnetic forces depend on the sign of the charge; the gravitational force does not', ['All three depend on the sign of the charge', 'Only the gravitational force depends on the sign of the charge', 'None depends on the sign of the charge'], 'Mass is always positive; charge can be either sign.', ['C1: charge sign reverses E and B forces', 'C1: gravity always attractive'])
N('M', 4, 'At what speed would the magnetic force on a proton in a 0.10 T field have the same size as the electric force on it in a 2.0 × 10⁴ V m⁻¹ field?', 2.0e4 / 0.10, 'm s⁻¹',
  'BQv = EQ, so v = E/B = 2.0 × 10⁴ ÷ 0.10 = 2.0 × 10⁵ m s⁻¹', ['M1: BQv = EQ', 'C1: v = E/B', 'C1: value'], sig=2, aq='v')
M('M', 3, 'How are g, E and B each defined?', 'g = F/m, E = F/Q, B = F/(IL)', ['g = mF, E = QF, B = ILF', 'g = F/m, E = F/Q, B = F/Q', 'g = m/F, E = Q/F, B = IL/F'], 'Each is force per unit of the property that the field acts on.', ['C1: force per unit property', 'C1: B uses IL'])
N('M', 3, 'A proton falls 0.10 m in the Earth\'s gravitational field. Separately, it moves 0.10 m along an electric field of 100 V m⁻¹. Calculate (work done by the electric field) ÷ (work done by gravity).' + take('e', 'mp', 'g'), QE * 100 * 0.10 / (MP * g * 0.10), None,
  f'W_E = 1.60 × 10⁻¹⁹ × 100 × 0.10 = 1.6 × 10⁻¹⁸ J. W_g = 1.67 × 10⁻²⁷ × 9.81 × 0.10 = {sf(MP * 9.81 * 0.1)} J. Ratio = 1.6 × 10⁻¹⁸ ÷ {sf(MP * 9.81 * 0.1, 4)} = {sf(1.6e-18 / (MP * 9.81 * 0.1))}', ['C1: W = EQd', 'C1: W = mgh'], aq='ratio')
N('M', 3, 'A helium nucleus (charge 2e) moves at 1.0 × 10⁵ m s⁻¹ parallel to an electric field of 2.0 × 10⁴ V m⁻¹ and at right angles to a magnetic field of 0.10 T. Calculate the size of the resultant force on it, in units of 10⁻¹⁵ N.' + take('e'), 2 * QE * sqrt((2.0e4) ** 2 + (1.0e5 * 0.10) ** 2), '10⁻¹⁵ N',
  f'F_E = 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ = 6.4 × 10⁻¹⁵ N. F_B = 2 × 1.60 × 10⁻¹⁹ × 1.0 × 10⁵ × 0.10 = 3.2 × 10⁻¹⁵ N, at right angles to F_E. Resultant = √((6.4 × 10⁻¹⁵)² + (3.2 × 10⁻¹⁵)²) = {sf(2 * QE * sqrt(4e8 + 1e8))} N', ['C1: both forces', 'C1: Pythagoras'], aq='F')
M('M', 3, 'A charged particle moves along the field lines. For which field is the force on it zero?', 'A magnetic field', ['An electric field', 'A gravitational field', 'All three fields'], 'For motion parallel to B, sin θ = 0.', ['C1: F = BQv sin θ', 'C1: θ = 0'])
N('M', 3, 'Calculate the electric field strength that would give an electron the same size of force as its weight at the Earth\'s surface, in units of 10⁻¹¹ V m⁻¹.' + take('me', 'g', 'e'), ME * g / QE, '10⁻¹¹ V m⁻¹',
  f'eE = mg, so E = 9.11 × 10⁻³¹ × 9.81 ÷ 1.60 × 10⁻¹⁹ = {sf(ME * 9.81 / QE)} V m⁻¹', ['M1: eE = mg', 'C1: substitution'], aq='E')
M('M', 3, 'A charged particle moves at constant speed in a circle in a uniform field. Which field could be providing the centripetal force?', 'A magnetic field', ['A uniform electric field', 'A uniform gravitational field', 'None of these'], 'Only the magnetic force stays perpendicular to the velocity as the particle turns.', ['C1: force always perpendicular to v', 'C1: magnetic'])
# hard
N('H', 6, 'A velocity selector has parallel plates 4.0 mm apart with a p.d. of 600 V, and a magnetic field of 0.050 T at right angles to the electric field. (a) Calculate the electric field strength. (b) Calculate the speed of ions that pass through undeflected. (c) Explain why faster ions are deflected, and in which direction relative to the electric force. Give only the answer to (b).', 600 / 4.0e-3 / 0.050, 'm s⁻¹',
  '(a) E = V/d = 600 ÷ 4.0 × 10⁻³ = 1.5 × 10⁵ V m⁻¹. (b) EQ = BQv, so v = E/B = 1.5 × 10⁵ ÷ 0.050 = 3.0 × 10⁶ m s⁻¹. (c) For faster ions BQv > EQ, so the magnetic force wins and they are deflected opposite to the electric force.',
  ['C1: E = V/d', 'M1: EQ = BQv', 'C1: v = E/B', 'B1: magnetic force larger for faster ions', 'B1: direction opposite to electric force'], sig=2, aq='v')
N('H', 5, 'A proton moves horizontally at 2.0 × 10⁵ m s⁻¹ at right angles to the Earth\'s field of 5.0 × 10⁻⁵ T, through the fair-weather electric field of 120 V m⁻¹. (a) Calculate the magnetic force. (b) Calculate the electric force. (c) Calculate (electric force) ÷ (magnetic force) and comment on the gravitational force. Give only the ratio from (c).' + take('e'), (120 * QE) / (5.0e-5 * QE * 2.0e5), None,
  f'(a) F_B = 5.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = {sf(5e-5 * QE * 2e5)} N. (b) F_E = 120 × 1.60 × 10⁻¹⁹ = {sf(120 * QE)} N. (c) Ratio = {sf(120 * QE, 4)} ÷ {sf(5e-5 * QE * 2e5, 4)} = {sf(120 / (5e-5 * 2e5))}. Gravity, about 1.6 × 10⁻²⁶ N, is negligible.',
  ['C1: F_B', 'C1: F_E', 'C1: ratio', 'B1: gravity negligible'], sig=2, aq='ratio')
N('H', 6, 'A dust grain of mass 1.0 × 10⁻¹⁵ kg carries a charge of 1.6 × 10⁻¹⁸ C and moves at 2.0 m s⁻¹ at right angles to a magnetic field of 0.10 T. (a) Calculate the magnetic force. (b) Calculate the weight. (c) Comment on which force dominates. (d) Calculate the vertical electric field that would support the grain. Give only the answer to (d).' + take('g'), 1.0e-15 * g / 1.6e-18, 'V m⁻¹',
  f'(a) F_B = 0.10 × 1.6 × 10⁻¹⁸ × 2.0 = 3.2 × 10⁻¹⁹ N. (b) W = 1.0 × 10⁻¹⁵ × 9.81 = {sf(1e-15 * 9.81)} N. (c) Gravity is about 3 × 10⁴ times larger, because the grain is massive and slow. (d) EQ = mg, so E = {sf(1e-15 * 9.81, 4)} ÷ 1.6 × 10⁻¹⁸ = {sf(1e-15 * 9.81 / 1.6e-18)} V m⁻¹',
  ['C1: F = BQv', 'C1: W = mg', 'B1: gravity dominates', 'M1: EQ = mg', 'C1: value'], aq='E')
N('H', 5, 'A proton starts from rest and moves 0.050 m along a uniform electric field of 2.0 × 10⁴ V m⁻¹, while a magnetic field also acts on it. (a) Calculate the work done by the electric field. (b) Explain why the magnetic field does no work. (c) Calculate the final speed of the proton. Give only the answer to (c).' + take('e', 'mp'), sqrt(2 * QE * 2.0e4 * 0.050 / MP), 'm s⁻¹',
  f'(a) W = EQd = 2.0 × 10⁴ × 1.60 × 10⁻¹⁹ × 0.050 = 1.6 × 10⁻¹⁶ J. (b) The magnetic force is always perpendicular to the velocity. (c) ½mv² = W, so v = √(2 × 1.6 × 10⁻¹⁶ ÷ 1.67 × 10⁻²⁷) = {sf(sqrt(3.2e-16 / MP))} m s⁻¹',
  ['C1: W = EQd', 'B1: magnetic force perpendicular', 'M1: work = gain in KE', 'C1: speed'], aq='v')
N('H', 6, 'An electron moves at 1.0 × 10⁶ m s⁻¹ at right angles to a magnetic field of 1.0 mT. (a) Explain why its path is a circle. (b) Show that the radius is r = mv/eB. (c) Calculate the radius, in mm. Give only the answer to (c).' + take('me', 'e'), ME * 1.0e6 / (QE * 1.0e-3) * 1000, 'mm',
  f'(a) The force is constant in size and always perpendicular to the velocity, so it provides a centripetal force. (b) eBv = mv²/r gives r = mv/eB. (c) r = 9.11 × 10⁻³¹ × 1.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁻³) = {sf(ME * 1e6 / (QE * 1e-3))} m. In mm: {sf(ME * 1e6 / (QE * 1e-3), 4)} × 1000 = {sf(ME * 1e6 / (QE * 1e-3) * 1000)}',
  ['B1: force perpendicular, constant size', 'M1: eBv = mv²/r', 'C1: substitution', 'C1: conversion', 'B1: radius independent of direction of entry'], aq='r')
N('H', 5, 'A proton moves at 1.0 × 10⁶ m s⁻¹. (a) Calculate its acceleration in an electric field of 1.0 × 10⁴ V m⁻¹. (b) Calculate its acceleration when moving at right angles to a magnetic field of 0.10 T. (c) Calculate (magnetic acceleration) ÷ (electric acceleration), and show that it equals vB/E. Give only the answer to (c).' + take('e', 'mp'), (QE * 1.0e6 * 0.10 / MP) / (QE * 1.0e4 / MP), None,
  f'(a) a_E = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10⁴ ÷ 1.67 × 10⁻²⁷ = {sf(QE * 1e4 / MP)} m s⁻². (b) a_B = eBv/m = 1.60 × 10⁻¹⁹ × 0.10 × 1.0 × 10⁶ ÷ 1.67 × 10⁻²⁷ = {sf(QE * 1e5 / MP)} m s⁻². (c) Ratio = vB/E = 1.0 × 10⁶ × 0.10 ÷ 1.0 × 10⁴ = 10',
  ['C1: a_E', 'C1: a_B', 'M1: ratio = vB/E', 'C1: value'], sig=2, aq='ratio')
N('H', 6, 'Protons moving at 2.0 × 10⁵ m s⁻¹ pass undeflected through crossed electric and magnetic fields. The electric field is 1.0 × 10³ V m⁻¹ and the field region is 0.10 m long. (a) Calculate the magnetic flux density. (b) The magnetic field is switched off. Calculate the time each proton spends in the field region. (c) Calculate the sideways deflection caused by the electric field alone, in cm. Give only the answer to (c).' + take('e', 'mp'), 0.5 * QE * 1.0e3 / MP * (0.10 / 2.0e5) ** 2 * 100, 'cm',
  f'(a) B = E/v = 1.0 × 10³ ÷ 2.0 × 10⁵ = 5.0 × 10⁻³ T. (b) t = 0.10 ÷ 2.0 × 10⁵ = 5.0 × 10⁻⁷ s. (c) a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10³ ÷ 1.67 × 10⁻²⁷ = {sf(QE * 1e3 / MP)} m s⁻²; y = ½at² = 0.5 × {sf(QE * 1e3 / MP, 4)} × (5.0 × 10⁻⁷)² = {sf(0.5 * QE * 1e3 / MP * 2.5e-13)} m. In cm: {sf(0.5 * QE * 1e3 / MP * 2.5e-13, 4)} × 100 = {sf(0.5 * QE * 1e3 / MP * 2.5e-13 * 100)}',
  ['C1: B = E/v', 'C1: t = L/v', 'C1: a = eE/m', 'M1: y = ½at²', 'C1: conversion'], aq='y')
N('H', 5, 'A proton moves at 1.0 × 10⁶ m s⁻¹ in a circle in a field of 0.20 T. (a) Calculate the radius of the circle, using r = mv/BQ. (b) State the work done by the magnetic field in half a revolution. (c) An electric field of 5.0 × 10³ V m⁻¹ acts along the diameter instead. Calculate the work it would do on the proton over a displacement of one diameter, in units of 10⁻¹⁷ J. Give only the answer to (c).' + take('mp', 'e'), QE * 5.0e3 * 2 * MP * 1.0e6 / (0.20 * QE), '10⁻¹⁷ J',
  f'(a) r = 1.67 × 10⁻²⁷ × 1.0 × 10⁶ ÷ (0.20 × 1.60 × 10⁻¹⁹) = {sf(MP * 1e6 / (0.2 * QE))} m. (b) Zero: the force is always perpendicular to the motion. (c) W = EQ × 2r = 5.0 × 10³ × 1.60 × 10⁻¹⁹ × 2 × {sf(MP * 1e6 / (0.2 * QE), 4)} = {sf(5e3 * QE * 2 * MP * 1e6 / (0.2 * QE))} J',
  ['C1: r = mv/BQ', 'B1: no work by B', 'M1: W = EQd with d = 2r', 'C1: value'], aq='W')
